MODULE Main;
IMPORT IO, Fmt;

PROCEDURE Factorial(n: CARDINAL): INTEGER =
  BEGIN
    IF n <= 1 THEN RETURN 1 ELSE RETURN n * Factorial(n - 1) END
  END Factorial;

BEGIN
  IO.Put(Fmt.Int(Factorial(10)) & "\n")
END Main.

