MODULE Main;
IMPORT IO, Fmt, IntSeq;           (* IntSeq = the generic Sequence(Integer) *)

TYPE
  Pred = PROCEDURE (x: INTEGER): BOOLEAN;
  Func = PROCEDURE (x: INTEGER): INTEGER;

PROCEDURE IsEven(x: INTEGER): BOOLEAN = BEGIN RETURN x MOD 2 = 0 END IsEven;
PROCEDURE Square(x: INTEGER): INTEGER = BEGIN RETURN x * x END Square;

PROCEDURE FilterMap(xs: IntSeq.T; keep: Pred; f: Func): IntSeq.T =
  VAR out := NEW(IntSeq.T).init();
  BEGIN
    FOR i := 0 TO xs.size() - 1 DO
      WITH x = xs.get(i) DO
        IF keep(x) THEN out.addhi(f(x)) END
      END
    END;
    RETURN out
  END FilterMap;

VAR xs := NEW(IntSeq.T).init(); ys: IntSeq.T; line := "";
BEGIN
  FOR i := 1 TO 10 DO xs.addhi(i) END;
  ys := FilterMap(xs, IsEven, Square);
  FOR i := 0 TO ys.size() - 1 DO
    IF i > 0 THEN line := line & " " END;
    line := line & Fmt.Int(ys.get(i))
  END;
  IO.Put(line & "\n")
END Main.

shapes.code:
MODULE Main;
IMPORT IO, Fmt;

TYPE
  Shape = OBJECT METHODS area(): INTEGER END;       (* no default: abstract *)
  Rectangle = Shape OBJECT width, height: INTEGER OVERRIDES area := RectArea END;
  Triangle = Shape OBJECT base, height: INTEGER OVERRIDES area := TriArea END;

PROCEDURE RectArea(r: Rectangle): INTEGER = BEGIN RETURN r.width * r.height END RectArea;
PROCEDURE TriArea(t: Triangle): INTEGER = BEGIN RETURN t.base * t.height DIV 2 END TriArea;

PROCEDURE Show(name: TEXT; s: Shape) =
  BEGIN
    IO.Put(name & ": " & Fmt.Int(s.area()) & "\n")
  END Show;

BEGIN
  Show("Rectangle", NEW(Rectangle, width := 3, height := 4));
  Show("Triangle", NEW(Triangle, base := 10, height := 3))
END Main.

signature.code:
MODULE Main;
IMPORT IO, Fmt;

EXCEPTION Empty;

TYPE
  Stack <: Public;                  (* opaque: some subtype of Public *)
  Public = OBJECT METHODS push(x: INTEGER); pop(): INTEGER RAISES {Empty} END;

REVEAL                              (* the hidden representation *)
  Stack = Public BRANDED OBJECT
    items: ARRAY [1 .. 8] OF INTEGER;
    n := 0;
  OVERRIDES
    push := Push;
    pop := Pop;
  END;

PROCEDURE Push(s: Stack; x: INTEGER) = BEGIN INC(s.n); s.items[s.n] := x END Push;

PROCEDURE Pop(s: Stack): INTEGER RAISES {Empty} =
  BEGIN
    IF s.n = 0 THEN RAISE Empty END;
    DEC(s.n);
    RETURN s.items[s.n + 1]
  END Pop;

VAR s := NEW(Stack);                (* a traced reference: garbage-collected *)
BEGIN
  FOR i := 1 TO 3 DO s.push(i * i) END;
  TRY
    LOOP IO.Put(Fmt.Int(s.pop()) & " ") END     (* left only by the exception *)
  EXCEPT
    Empty => IO.Put("empty\n")
  END
END Main.
